import type {
  Connection,
  EnterpriseConnection,
} from "@auth0/auth0-acul-react/types";

import { getIcon } from "./iconUtils";

export type SocialConnection = Connection | EnterpriseConnection;

interface SocialProviderDetails {
  displayName: string;
  iconComponent: React.ReactNode | null;
}

/**
 * Map of Auth0 connection strategies to their human-readable display names.
 * The Auth0 SDK strips display_name from social connections when processing
 * the context, so we maintain this map for known social providers.
 */
const STRATEGY_DISPLAY_NAMES: Record<string, string> = {
  "google-oauth2": "Google",
  apple: "Apple",
  windowslive: "Microsoft Account",
  facebook: "Facebook",
  twitter: "Twitter",
  github: "GitHub",
  linkedin: "LinkedIn",
  dropbox: "Dropbox",
  bitbucket: "Bitbucket",
  "yahoo": "Yahoo",
  paypal: "PayPal",
  "amazon": "Amazon",
  instagram: "Instagram",
  salesforce: "Salesforce",
  "salesforce-sandbox": "Salesforce Sandbox",
  "salesforce-community": "Salesforce Community",
  line: "LINE",
  renren: "Renren",
  vkontakte: "VKontakte",
  yammer: "Yammer",
  "thirty-seven-signals": "Basecamp",
  fitbit: "Fitbit",
  baidu: "Baidu",
  "gg-basic": "GG",
  "miicard": "miiCard",
  "yandex": "Yandex",
  "dwolla": "Dwolla",
  "wordpress": "WordPress",
  "shopify": "Shopify",
  "custom": "Custom",
};

/**
 * Generates a display name for a social connection.
 *
 * Priority order:
 * 1. Static map by strategy (covers all known social providers with correct names)
 * 2. options.displayName for EnterpriseConnection (camelCase, SDK-processed from display_name)
 * 3. Capitalize connection.name as last resort
 */
const generateDisplayName = (connection: SocialConnection): string => {
  // First: check static map by strategy (handles social providers correctly)
  if (connection.strategy && STRATEGY_DISPLAY_NAMES[connection.strategy]) {
    return STRATEGY_DISPLAY_NAMES[connection.strategy];
  }

  // Second: displayName from EnterpriseConnection options (SDK converts display_name → displayName)
  if ("options" in connection && connection.options?.displayName) {
    return connection.options.displayName;
  }

  // Fallback: capitalize the connection name
  if (connection.name) {
    return connection.name
      .split(/[-_]/)
      .map((word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())
      .join(" ");
  }

  // Last resort: use strategy
  if (connection.strategy) {
    return (
      connection.strategy.charAt(0).toUpperCase() + connection.strategy.slice(1)
    );
  }

  return "Login Provider";
};

/**
 * Gets the display details (displayName, iconComponent) for a social connection.
 */
export const getSocialProviderDetails = (
  connection: SocialConnection
): SocialProviderDetails => {
  const displayName = generateDisplayName(connection);
  const iconComponent = getIcon(connection.strategy);

  return {
    displayName,
    iconComponent,
  };
};
